import { Table, BooleanColumn, StringColumn, ReferenceColumn } from '../../db'

export const sys_ws_header = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Scripted REST Header',
    name: 'sys_ws_header',
    schema: {
        required: BooleanColumn({
            label: [
                {
                    hint: 'Require this header in all requests to the resource',
                    label: 'Is required',
                    plural: 'Is required',
                },
            ],
            maxLength: 30,
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The name of the header. Appears in API documentation.',
                    label: 'Header name',
                    plural: 'Header names',
                },
            ],
            mandatory: true,
        }),

        web_service_definition: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The API this header belongs to',
                    label: 'API definition',
                    plural: 'API definitions',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_ws_definition',
        }),
        example_value: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'An example of a valid value for this header. Appears in API documentation.',
                    label: 'Example value',
                    plural: 'Example values',
                },
            ],
            maxLength: 255,
        }),
        short_description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The description of the header. Appears in API documentation.',
                    label: 'Short description',
                    plural: 'Short descriptions',
                },
            ],
            maxLength: 80,
        }),
    },
    textIndex: true,
})
